                  reply: "你补出的前提二太强了。人的实践塑造的东西常常极难改变：语言、家庭形式、市场惯例都依赖实践，却不因谁说一句就变。要保住这条推理，你得把它弱化成「原则上可以改变」，但那样得到的只是「不是自然必然的」，推不出「不应当约束我们」。从「可改变」到「不应当约束」还差一整条规范前提。",
                  next: "t4"
