          scheme: "假言三段论（含一条把「损害自我关系」界定为压迫的规范前提）",
          valid: true,
          sound: false,
          gap: "最弱的是 P3，而不是前两条前提：P1 是泰勒的经验性人类学主张（可争，但已被广泛接受），P2 是从 P1 的分析性延伸，真正承重的是「损害自我关系即构成压迫」这条界定。它可被两条理由推翻。第一，把伤害的门槛设在自我关系上，会使压迫的范围急剧扩大——任何拒绝、轻视与失败都可能落入其中，于是「压迫」失去区分力。第二，有人会主张压迫的标准应当落在**可行能力或机会**上（能不能做某事、能不能进入某个领域），此时自我关系受损只是伴随现象而不是压迫的构成要件。要保住结论，需要说明为什么自我关系的损害不能被还原成机会的损害，并给出一条界线把「压迫性的贬低」与「日常的失望」分开——泰勒本人并未给出细致的界线，这是他的论证最常被追问之处。另一条攻击路径是攻击 P1 的普遍性：若某些人的身份主要形成于制度处境而非他人的看待，那么 P2 的适用面会缩小。"
