            "把福柯读成「权力就是压制」。福柯最反直觉的主张恰恰是权力是**生产性的**：它生产知识、分类、主体、「正常」的界线。若把它读成压抑模型，你就无法解释本讲开头那个例子——没有禁令，行为照样被塑造。",
