            "把规训与法律惩罚混为一谈。法律处理的是「合法与非法」，针对已发生的行为；规训处理的是「正常与异常」，可以针对你是一个什么样的人（不够快、不够合群、评级靠后）。后者比前者更细致，因此也更难被「取消某条禁令」这种方式摆脱。",
            "把「系统对生活世界的殖民」读成「效率不好」。殖民的症状不是效率低，而是**意义丧失与规范混乱**：事情做成了，但「我们为什么这样做」不再有答案，或者答案只能由指标提供。批评哈贝马斯时也必须按这个版本批评，否则就是稻草人。",
            "以为批判必须有绝对立场才能进行。找出隐含的规范前提是批判的必修课，但这不等于必须先建立一套完整的道德哲学。内在批判（用对方承认的标准指出其不一致）、商谈条件（指出对话已经预设了什么）、权利论证都是可行的立足点，它们各有局限。",
