          front: "弗雷泽（Nancy Fraser）与哈贝马斯对福柯的共同批评是什么？",
          back: "他们都指出福柯缺少规范标准：他拒绝说明什么样的权力安排更可接受，因此难以区分较好的与较坏的安排。这一批评的要害是：如果一切知识都与权力纠缠，那么福柯自己的分析凭什么例外？另一条相关批评是「泛权力论」风险——若权力无处不在，这个词就无法排除任何东西，也就失去了区分力（此处为常见批评的概述，非某一文本的引文）。",
