          hidden: true,
          form: "P1: Product(x, social process)；P2: ∀x(Product(x, social process) → Could-be-otherwise(x))；P3: ∀x(Could-be-otherwise(x) → ¬Grounded(x))；C: ¬Grounded(critique)",
          scheme: "假言三段论（两段蕴含传递后得出一个普遍结论）",
          valid: true,
          sound: false,
          gap: "最弱的是 P3，它把「偶然」与「没有根据」直接等同。这条前提一旦被推翻，整条论证就断了：诺言、合同、度量衡、语言都是历史产物，也都可以是别的样子，但这不妨碍它们有根据（诺言有约束力、度量衡有统一带来的可协调性）。要推翻 P3，只需指出某个既偶然又有根据的东西。此外还有一条独立的反驳针对结论：若结论成立，那么「批判没有支点」这句话本身也没有支点，于是它没有资格要求我们接受——这就是自我指涉困难。要保住这条论证，必须把它从普遍形式改成局部形式（例如「某些领域的标准在跨框架比较时缺乏中立尺度」），但那已不足以支持原结论。注意 P2 也需要检验：「凡社会产物都可以是别的样子」在某些情形下过强——货币制度、语言的核心结构在功能约束下并非任意可换（第 1 讲）。"
