          sound: false,
          gap: "最弱的是 P1 到 P2 的那一步跳跃：从「参与者事实上预设了某些条件」推不出「这些条件不能被任意取消」。参与者可能只是**不得不**在当下这样说话（否则没人听他），而这属于事实上的约束，不是规范上的约束——从「无法避免地预设」到「有义务遵守」，中间还差一条桥接前提（这正是本课第 1 讲所讲的从「是」到「应当」那一步）。第二种攻击针对 P3：把「所有受影响者的同意」当作有效性的条件，会面临划界问题（谁算受影响者）与反事实问题（永远无法实际取得的那种同意如何判定是否存在）。要保住结论，需要说明这条回溯论证与其他先验论证的差别在哪里；要推翻它，最有效的做法是指出一个事实上无法避免但明显不具规范效力的预设。"
