                  reply: "「确实充满攻击」是一个观察，不是对那个总断言的验证。要支持「摧毁了可能」，你需要说明攻击性表达的增加是由媒介结构造成的（而不是既有的极化选择了这种媒介），并对「以前更好」给出可比的数据。仅凭当下的印象作出总体判断，正是本讲点名的情绪化论述。",
                  next: "t5"
