              prompt: "最后一问综合整门课：面对信用评分或算法定价这类安排，按「它改变了什么社会关系 → 谁受益谁受损 → 需要什么规范回应」这条链，你认为最难的一步是哪一步？",
              note: "最后一问要求读者对整门课的工具做一次自我评估，并收束课程。",
