                  verdict: "good",
                  reply: "这是本课最想让你带走的一句话。前两步是描述与因果的工作（可以靠证据完成），第三步必须跨过从「是」到「应当」的那一步，因此必须写出你依赖的规范前提并为之辩护。安德森的关系性平等、弗雷泽的双维度、哈贝马斯的商谈条件、福柯式的「不被固定」都可以充当这一步，但它们各有代价，都必须自证。三句结论收在这里：（一）技术改变的是关系与可争议性，不只是效率；（二）责任鸿沟是现有制度失灵的诊断，因此指向制度设计而不是免责；（三）任何规范回应都要交代自己的前提与可反驳条件。"
