          prompt: "自选一个具体的技术案例（例如：网约车的动态定价、外卖平台的派单与超时扣分、电商的个性化定价、求职平台的自动筛选、保险公司的行为定价、学校的在线监考系统、公共场所的人脸识别），写 900~1100 字，严格按四步走完这条链：（1）**描述**——这项技术安排在什么环节、对谁、做了什么，当事人能否知道规则、能否申诉（只写可核对的事实，不写评价）；（2）**关系与得失**——它改变了哪些社会关系，谁受益、谁受损，并说明受损是否集中在特定群体（注意分布而不只是均值）；（3）**规范前提**——写出你的规范回应所依赖的前提，说明它属于哪一类（程序、关系性平等、相关性要求、后果计算等），并为此前提提供辩护；（4）**对称检验与可反驳条件**——按同样三步检查支持这项安排的最强论证，并写出：如果哪一项事实或哪一条前提被推翻，你的结论会改变成什么。",
