          sample: "（以下是示范片段，不是标准答案）本文分析的对象是某网约车平台的动态定价：在需求集中的时段，同一段路程的报价按实时供需倍数上浮，乘客在下单前可以看到倍数，但无法知道倍数如何计算，也无法与平台就某一次报价争议。可核对的事实是：倍数在界面上可见、历史价格不可全量查询、平台保留调整算法的权利且不公开具体规则。（下略）",
